//! Mapping attributes set to their default and set then cleared: the port's
//! `test_*` methods and dumps against C's `astTest` and C's dump.
//!
//! A set attribute is written whenever it is set, its default included, and
//! a cleared one is written commented, as its default, only when the class
//! marks it "helpful" (`Zoom`, `LutInt`, `PlrLg`, `PcdCen`, `Disco` and the
//! GrismMap parameters).
//!
//! `attr_test_clear_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/attr_test_clear_probe.c`.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "attr_test_clear_oracle/cases.rs"]
mod cases;

use ast_core::mappings::{
    GrismMap, LutInterp, LutMap, Mapping, MathMap, PcdMap, PermMap, PolyMap, PolyTerm, SphMap,
    SplineMap, WcsMap, WcsProjection, ZoomMap,
};
use ast_core::{AnyObject, from_native_string, to_native_string};

/// The Mapping a case builds, and the port's answer for each attribute the
/// case tests, in the probe's order.
fn build(name: &str) -> (AnyObject, Vec<bool>) {
    let perm = || PermMap::new(&[2, 1], &[2, 1], &[]).unwrap();
    let lut = || {
        let mut m = LutMap::new(&[0.0, 1.0, 4.0, 9.0, 16.0], 0.0, 1.0).unwrap();
        m.set_interp(LutInterp::Linear);
        m.set_lut_epsilon(1.0e-10);
        m
    };
    let poly = || {
        let term = |out_axis, powers| PolyTerm {
            coeff: 1.0,
            powers,
            out_axis,
        };
        let mut m = PolyMap::new(2, 2, &[term(1, vec![1, 0]), term(2, vec![0, 1])], None).unwrap();
        m.set_niter_inverse(4);
        m.set_tol_inverse(1.0e-6);
        m
    };
    let spline = || {
        let mut m = SplineMap::new(
            1,
            1,
            1,
            1,
            vec![0.0, 1.0],
            vec![0.0, 1.0],
            vec![1.5],
            vec![2.5],
        )
        .unwrap();
        m.set_out_unit(false);
        m.set_inv_niter(6);
        m.set_inv_tol(1.0e-6);
        m
    };
    let sph = || {
        let mut m = SphMap::new();
        m.set_unit_radius(false);
        m.set_polar_long(1.0);
        m
    };
    let math = || {
        let mut m = MathMap::new(1, 1, &["y=x"], &["x=y"]).unwrap();
        m.set_simp_fi(false);
        m.set_simp_if(false);
        m
    };
    match name {
        "permmap_split_default" => {
            let mut m = perm();
            m.set_perm_split(false);
            let t = vec![m.test_perm_split()];
            (AnyObject::PermMap(m), t)
        }
        "permmap_split_cleared" => {
            let mut m = perm();
            m.set_perm_split(true);
            m.clear_perm_split();
            let t = vec![m.test_perm_split()];
            (AnyObject::PermMap(m), t)
        }
        "zoommap_cleared" => {
            let mut m = ZoomMap::new(2, 3.0).unwrap();
            m.clear_zoom();
            assert_eq!(m.zoom(), 1.0);
            let t = vec![m.test_zoom()];
            (AnyObject::ZoomMap(m), t)
        }
        "lutmap_default" => {
            let m = lut();
            let t = vec![m.test_interp(), m.test_lut_epsilon()];
            (AnyObject::LutMap(m), t)
        }
        "lutmap_cleared" => {
            let mut m = lut();
            m.clear_interp();
            m.clear_lut_epsilon();
            assert_eq!(m.interp(), LutInterp::Linear);
            assert_eq!(m.lut_epsilon(), f64::EPSILON);
            let t = vec![m.test_interp(), m.test_lut_epsilon()];
            (AnyObject::LutMap(m), t)
        }
        "polymap_default" => {
            let m = poly();
            let t = vec![m.test_niter_inverse(), m.test_tol_inverse()];
            (AnyObject::PolyMap(m), t)
        }
        "polymap_cleared" => {
            let mut m = poly();
            m.clear_niter_inverse();
            m.clear_tol_inverse();
            assert_eq!((m.niter_inverse(), m.tol_inverse()), (4, 1.0e-6));
            let t = vec![m.test_niter_inverse(), m.test_tol_inverse()];
            (AnyObject::PolyMap(m), t)
        }
        "wcsmap_pv_cleared" => {
            let mut m = WcsMap::new(2, WcsProjection::Sin, 1, 2).unwrap();
            m.set_pv(2, 1, 0.1).unwrap();
            m.set_pv(2, 2, 0.2).unwrap();
            m.clear_pv(2, 1).unwrap();
            let t = vec![m.test_pv(2, 1), m.test_pv(2, 2)];
            (AnyObject::WcsMap(m), t)
        }
        "pcdmap_cleared" => {
            let mut m = PcdMap::new(1.0e-5, [1.0, 2.0]);
            m.clear_disc();
            m.clear_pcd_cen(1).unwrap();
            let t = vec![
                m.test_disc(),
                m.test_pcd_cen(1).unwrap(),
                m.test_pcd_cen(2).unwrap(),
            ];
            (AnyObject::PcdMap(m), t)
        }
        "grismmap_cleared" => {
            let mut m = GrismMap::default_map();
            m.set_grism_nr(1.5);
            m.set_grism_m(2);
            m.clear_grism_nr();
            m.clear_grism_m();
            let t = vec![m.test_grism_nr(), m.test_grism_m()];
            (AnyObject::GrismMap(m), t)
        }
        "splinemap_default" => {
            let m = spline();
            let t = vec![m.test_out_unit(), m.test_inv_niter(), m.test_inv_tol()];
            (AnyObject::SplineMap(m), t)
        }
        "splinemap_cleared" => {
            let mut m = spline();
            m.clear_out_unit();
            m.clear_inv_niter();
            m.clear_inv_tol();
            let t = vec![m.test_out_unit(), m.test_inv_niter(), m.test_inv_tol()];
            (AnyObject::SplineMap(m), t)
        }
        "sphmap_default" => {
            let m = sph();
            let t = vec![m.test_unit_radius(), m.test_polar_long()];
            (AnyObject::SphMap(m), t)
        }
        "sphmap_cleared" => {
            let mut m = sph();
            m.clear_unit_radius();
            m.clear_polar_long();
            let t = vec![m.test_unit_radius(), m.test_polar_long()];
            (AnyObject::SphMap(m), t)
        }
        "mathmap_default" => {
            let m = math();
            let t = vec![m.test_simp_fi(), m.test_simp_if()];
            (AnyObject::MathMap(m), t)
        }
        "mathmap_cleared" => {
            let mut m = math();
            m.clear_simp_fi();
            m.clear_simp_if();
            let t = vec![m.test_simp_fi(), m.test_simp_if()];
            (AnyObject::MathMap(m), t)
        }
        "invert_set_zero" | "invert_once" | "invert_zero_inverted_twice" | "invert_cleared" => {
            let mut m = ZoomMap::new(1, 2.0).unwrap();
            match name {
                "invert_set_zero" => m.set_invert(false),
                "invert_once" => m.invert(),
                "invert_zero_inverted_twice" => {
                    m.set_invert(false);
                    m.invert();
                    m.invert();
                }
                _ => {
                    m.set_invert(true);
                    m.clear_invert();
                }
            }
            let t = vec![m.test_invert()];
            (AnyObject::ZoomMap(m), t)
        }
        _ => panic!("no Rust construction for case {name}"),
    }
}

#[test]
fn test_and_dump_match_the_c_library() {
    let mut failures = Vec::new();
    for &(name, tests, dump, _) in cases::CASES {
        let (obj, got) = build(name);
        let want: Vec<bool> = tests.iter().map(|&(_, t)| t).collect();
        if got != want {
            failures.push(format!("{name}: test {got:?}, C {tests:?}"));
        }
        let written = to_native_string(&obj).unwrap();
        if written != dump {
            failures.push(format!("{name}: dump\n{written}C:\n{dump}"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// Reading C's dump back gives what C's does. That is the same dump except
/// where a loader sets an attribute the dump left unset: C's LutMap loader
/// always sets LutInterp (lutmap.c:2586), so a cleared one comes back set.
#[test]
fn c_dumps_read_back_as_in_c() {
    for &(name, _, dump, read_back) in cases::CASES {
        let obj = from_native_string(dump).unwrap();
        assert_eq!(to_native_string(&obj).unwrap(), read_back, "{name}");
    }
}

/// The protected WcsMap flags clear back to their `true` defaults, and a
/// projection parameter or PolarLong set to `BAD_VALUE` is unset, AST__BAD
/// being C's unset value (wcsmap.c `TestPV`, sphmap.c:1441).
#[test]
fn protected_flags_clear_and_bad_unsets() {
    use ast_core::constants::BAD_VALUE;
    let mut w = WcsMap::new(2, WcsProjection::Sin, 1, 2).unwrap();
    w.set_lon_check(false);
    w.set_fits_proj(false);
    w.set_tpn_tan(false);
    w.clear_lon_check();
    w.clear_fits_proj();
    w.clear_tpn_tan();
    assert!(!w.test_lon_check() && !w.test_fits_proj() && !w.test_tpn_tan());
    assert!(w.lon_check() && w.fits_proj() && w.tpn_tan());
    w.set_pv(2, 1, 0.1).unwrap();
    w.set_pv(2, 1, BAD_VALUE).unwrap();
    assert!(!w.test_pv(2, 1));

    let mut s = SphMap::new();
    s.set_polar_long(1.0);
    s.set_polar_long(BAD_VALUE);
    assert!(!s.test_polar_long());
    assert_eq!(s.polar_long(), 0.0);
}

/// `set_invert` and `clear_invert` are C's `astSetInvert` and
/// `astClearInvert`, whose default is not inverted.
#[test]
fn set_and_clear_invert() {
    use ast_core::mappings::Mapping;
    let mut m = ZoomMap::new(1, 2.0).unwrap();
    m.set_invert(true);
    assert!(m.is_inverted());
    m.set_invert(true);
    assert!(m.is_inverted());
    m.clear_invert();
    assert!(!m.is_inverted());
}
